<script setup>
import {watch,ref,onUnmounted,computed} from 'vue';import axios from 'axios';import {message} from '../art';import {useForm,Head,usePage,Link} from '@inertiajs/vue3';import StudySheet from '../Components/StudySheet.vue';import TodayBento from '../Components/TodayBento.vue';import RoundBuilder from '../Components/RoundBuilder.vue';import SubjectPicker from '../Components/SubjectPicker.vue';import Errors from '../Components/Errors.vue';import {art,modes} from '../art';
const props=defineProps({catalog:Object,freshSubjects:Array,freshPreferences:Object,activeCatch:Number,today:Object}),page=usePage();
const mode=()=>new URL(page.url,'http://local').searchParams.get('mode')||'fresh';
const form=useForm({mode:['fresh','tutor','exam'].includes(mode())?mode():'fresh',count:20,subjects:[...(props.freshSubjects||props.catalog.subjects)],topics:[],topic_scope:'all',difficulty:'All',pool:'all',seed:Math.floor(Math.random()*4294967296),balance:false,minutes:30,fresh_unseen:props.freshPreferences?.fresh_unseen??7,fresh_balance:props.freshPreferences?.fresh_balance??true});
watch(()=>page.url,()=>{if(['fresh','tutor','exam'].includes(mode()))form.mode=mode()});
const isBento=computed(()=>mode()==='bento'),subjectsSheet=ref(null);
const catchPreview=ref(null),catchError=ref(''),checking=ref(false);let catchTimer,seq=0;
watch(()=>[form.mode,form.subjects.slice(),form.fresh_unseen,form.fresh_balance],()=>{clearTimeout(catchTimer);const id=++seq;catchPreview.value=null;catchError.value='';if(form.mode!=='fresh'||isBento.value)return;checking.value=true;catchTimer=setTimeout(async()=>{try{const r=await axios.post('/fresh-catch/preview',form.data());if(id===seq)catchPreview.value=r.data}catch(e){if(id===seq)catchError.value=message(e)}finally{if(id===seq)checking.value=false}},350)},{deep:true,immediate:true});
onUnmounted(()=>{clearTimeout(catchTimer);seq++});
function start(){form.post('/attempts')}
</script>
<template><Head :title="isBento?'Today’s Bento':modes[form.mode]"/><template v-if="isBento"><h1>Today's Bento</h1><TodayBento :subjects="catalog.subjects" :initial="today"/></template><template v-else><div class="page-title compact-title"><h1>{{modes[form.mode]}}</h1><img class="small-portrait" :src="art[form.mode==='fresh'?'temaki':form.mode==='exam'?'wasabi':'maki']" alt=""></div>
<div class="panel fresh-setup"><Errors :errors="form.errors"/><template v-if="form.mode==='fresh'"><div class="fresh-subjects"><div><h2>10 questions</h2><p>{{form.subjects.length?form.subjects.join(' · '):'Choose your subjects'}}</p></div><button @click="subjectsSheet.open()">Edit subjects</button></div><details class="catch-mix"><summary>Customize mix</summary><label>{{form.fresh_unseen}} unseen + {{10-form.fresh_unseen}} previously missed<input type="range" min="0" max="10" step="1" v-model.number="form.fresh_unseen"></label><label class="check"><input type="checkbox" v-model="form.fresh_balance">Balance subjects</label><p class="muted">If one pool is short, the other fills your catch.</p></details><div class="catch-preview"><p v-if="checking" role="status">Checking your catch…</p><p v-else-if="catchError" class="error" role="alert">{{catchError}}</p><template v-else-if="catchPreview"><strong>{{catchPreview.unseen}} unseen · {{catchPreview.missed}} previously missed</strong><div class="chips"><span v-for="(n,s) in catchPreview.coverage" :key="s">{{s}} {{n}}</span></div></template></div><Link v-if="activeCatch" class="button primary full" :href="'/attempts/'+activeCatch">Resume catch</Link><button v-else class="primary full" :disabled="!form.subjects.length||form.processing||checking||!catchPreview" @click="start">{{form.processing?'Starting…':'Start catch'}}</button><StudySheet ref="subjectsSheet" title="Catch subjects"><SubjectPicker :subjects="catalog.subjects" v-model="form.subjects"/><template #actions><span>{{form.subjects.length}} selected</span><button class="primary" :disabled="!form.subjects.length" @click="subjectsSheet.close()">Done</button></template></StudySheet></template><RoundBuilder v-else :key="form.mode" :form="form" :catalog="catalog" :busy="form.processing" @start="start"/></div></template></template>